// 要探測的路由。全部是 GET、唯讀，不會寫入任何資料。
const base = 'https://support.synctify.net';
return [
  { json: { label: 'A. REST 索引 /wp-json/',        url: base + '/wp-json/' } },
  { json: { label: 'B. 內建 /wp/v2/users/me',       url: base + '/wp-json/wp/v2/users/me?context=edit&_fields=id,name' } },
  { json: { label: 'C. 內建 /wp/v2/docs',           url: base + '/wp-json/wp/v2/docs?per_page=1&_fields=id' } },
  { json: { label: 'D. 自訂 /synctify/v1/settings', url: base + '/wp-json/synctify/v1/settings' } },
];

// 把回應整理成可以直接截圖給維運看的格式。
// 注意：靠位置對回探測清單——診斷用途夠了，不要拿這個寫法去做正式流程。
const KEEP = ['x-amzn-waf-action', 'x-cache', 'server', 'content-type', 'via', 'x-amz-cf-pop', 'www-authenticate'];
const probes = $('探測清單').all();
const rows = [];

$input.all().forEach((item, i) => {
  const r = item.json || {};
  const hdrs = {};
  for (const [k, v] of Object.entries(r.headers || {})) {
    if (KEEP.includes(k.toLowerCase())) hdrs[k.toLowerCase()] = v;
  }
  const raw = typeof r.body === 'string' ? r.body
            : typeof r.data === 'string' ? r.data
            : JSON.stringify(r.body ?? r.data ?? '');

  // WAF 的 challenge：HTTP 202 ＋ x-amzn-waf-action 標頭 ＋ HTML/空白內容。
  // miniOrange 的攔截：JSON，鍵是 status/error/error_description。
  // WordPress 原生：JSON，鍵是 code/message/data。
  let 判定 = '（看內容）';
  if (hdrs['x-amzn-waf-action']) 判定 = 'AWS WAF：' + hdrs['x-amzn-waf-action'];
  else if (/"error_description"|"error_reason"/.test(raw)) 判定 = 'REST 安全外掛（miniOrange）攔截';
  else if (/"code"\s*:\s*"rest_/.test(raw)) 判定 = 'WordPress 原生回應';
  else if (r.statusCode >= 200 && r.statusCode < 300) 判定 = '通過';

  rows.push({ json: {
    探測: probes[i]?.json?.label ?? ('#' + i),
    HTTP: r.statusCode,
    判定,
    標頭: hdrs,
    回應內容: (raw || '（空白）').slice(0, 400),
    執行時間: new Date().toISOString(),
  }});
});

return rows;
